package com.desktodo.app;
import android.app.*;import android.widget.*;import android.text.InputType;import org.json.*;import java.net.*;import java.nio.charset.StandardCharsets;
/** Optional hub. Invitations can only submit pending messages; owner accepts display writes. */
final class CommunityPanel {
 long lastExchange=0;
 final MainActivity a;CommunityPanel(MainActivity a){this.a=a;}
 android.content.SharedPreferences prefs(){return a.getSharedPreferences("mojian-community",0);}
 static String address(String raw)throws Exception{String value=DeskModel.normalizeOrigin(raw);URI u=new URI(value);String host=u.getHost();boolean local=privateHost(host);if(!u.getScheme().equals("https")&&!local)throw new Exception("远程共享服务必须使用HTTPS");return value;}
 static boolean privateHost(String host){if(host.equals("localhost")||host.equals("127.0.0.1"))return true;String[] p=host.split("\\.");if(p.length!=4)return false;int[] n=new int[4];try{for(int i=0;i<4;i++){if(!p[i].matches("0|[1-9][0-9]{0,2}"))return false;n[i]=Integer.parseInt(p[i]);if(n[i]>255)return false;}}catch(Exception e){return false;}return n[0]==10||(n[0]==192&&n[1]==168)||(n[0]==172&&n[1]>=16&&n[1]<=31);}
 JSONObject call(String path,String method,JSONObject body)throws Exception{String url=address(prefs().getString("url",""));String token=AgentVault.get(a,"hub");if(token.isEmpty())throw new Exception("请先配置共享服务凭据");return new JSONObject(new String(DeskApi.request(url+"/v1/"+path,method,body==null?null:body.toString().getBytes(StandardCharsets.UTF_8),"application/json",token),StandardCharsets.UTF_8));}
 void render(){LinearLayout l=a.card("可选共享服务");l.addView(a.text("自托管服务提供跨端完成记录、习惯与日期同步、模板库、数据插件和留言收件箱。手机直连不依赖它。公网地址需HTTPS，服务凭据与屏幕访问无关。",14,a.muted));EditText url=a.field(l,"共享服务地址",prefs().getString("url","")),key=a.field(l,"服务凭据（留空保留）","");key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);a.primary(l,"保存连接",()->{try{String dest=address(url.getText().toString());if(!prefs().getString("url","").isEmpty()&&!dest.equals(prefs().getString("url",""))&&key.length()==0)throw new Exception("服务地址变化，请重新填写该服务的凭据");if(key.length()>0)AgentVault.put(a,"hub",key.getText().toString());prefs().edit().putString("url",dest).apply();a.clearDraft("共享服务地址");a.clearDraft("服务凭据（留空保留）");a.hideKeyboard();a.toast("已保存，可选择下面的操作");}catch(Exception e){a.toast(e.getMessage());}});android.widget.CheckBox automatic=new android.widget.CheckBox(a);automatic.setText("前台自动共享记录（每分钟）");automatic.setMinHeight(a.dp(48));automatic.setChecked(prefs().getBoolean("autoSync",false));automatic.setOnCheckedChangeListener((v,on)->prefs().edit().putBoolean("autoSync",on).apply());l.addView(automatic);l.addView(a.text("开启后向此服务交换完成ID、习惯和重要日期；不上传地址、密钥或系统日历。安卓仅前台执行。",12,a.muted));a.button(l,"同步完成记录、习惯和重要日期",this::exchange);a.button(l,"浏览共享模板",()->browse("templates"));a.button(l,"浏览数据插件",()->browse("plugins"));a.button(l,"从JSON文件发布数据插件",()->a.startActivityForResult(new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(android.content.Intent.CATEGORY_OPENABLE),74));a.button(l,"将当前排版发布到此服务",()->{try{JSONObject value=DeskExtras.template(a.cfg,"共享桌面");a.work("发布模板",()->call("templates","POST",value),()->{a.message="模板已发布，不含个人数据";});}catch(Exception e){a.toast(e.getMessage());}});a.button(l,"查看留言收件箱",this::inbox);a.button(l,"发送一条留言",this::sendMessage);l.addView(a.text(prefs().getLong("lastSync",0)==0?"尚未同步":("上次共享同步 "+DeskModel.updatedTime(prefs().getLong("lastSync",0))),12,a.muted));}
 void autoExchange(){if(prefs().getBoolean("autoSync",false)&&!prefs().getString("url","").isEmpty()&&System.currentTimeMillis()-lastExchange>=60000&&!a.busy&&!a.editing&&!a.resolvingConflict&&!(a.getCurrentFocus() instanceof EditText))exchange();}
 void exchange(){lastExchange=System.currentTimeMillis();try{JSONObject previous=new JSONObject(prefs().getString("shared","{}"));JSONObject captured=SharedData.capture(previous,a.completions,a.tasks,a.cfg,System.currentTimeMillis());final JSONObject[] response={null};long revision=a.editRevision.snapshot();a.work("同步跨端记录",()->response[0]=call("state","POST",new JSONObject().put("data",captured)),()->{try{JSONObject shared=response[0].getJSONObject("data");if(revision!=a.editRevision.snapshot()){a.message="本机同步期间发生更改，请再次同步；本机内容未覆盖";return;}JSONArray nextLedger=SharedData.ledger(shared);JSONObject nextCfg=SharedData.apply(a.cfg,shared).put("sharedStats",true);boolean changed=!ScreenSync.same(a.completions,nextLedger)||!ScreenSync.same(a.cfg,nextCfg);a.completions=nextLedger;a.cfg=nextCfg;JSONArray retained=new JSONArray();JSONObject records=shared.optJSONObject("completions");for(int i=0;i<a.history.length();i++){JSONObject t=a.history.getJSONObject(i);JSONObject r=records==null?null:records.optJSONObject(t.optString("id"));if(r==null||!r.optBoolean("deleted")||!t.optString("recordType").equals("completed"))retained.put(t);}a.history=retained;prefs().edit().putString("shared",shared.toString()).putLong("lastSync",System.currentTimeMillis()).apply();if(changed){a.screenChanged();if(a.connected)a.ui.post(()->a.sync(false,false));}else a.persist();a.message="共享记录已同步，按任务ID去重统计";}catch(Exception e){a.toast(e.getMessage());}});}catch(Exception e){a.toast(e.getMessage());}}
 void publishPlugin(JSONObject plugin){try{validatePlugin(plugin);a.work("发布数据插件",()->call("plugins","POST",plugin),()->{a.message="数据插件已发布，可从插件库选择";});}catch(Exception e){a.toast(e.getMessage());}}
 void browse(String kind){final JSONObject[] response={null};a.work("读取共享扩展",()->response[0]=call(kind,"GET",null),()->{try{JSONArray list=response[0].getJSONArray("items");if(list.length()==0){a.toast("服务内还没有"+(kind.equals("templates")?"模板":"插件"));return;}String[] names=new String[list.length()];for(int i=0;i<names.length;i++)names[i]=list.getJSONObject(i).getString("name");new AlertDialog.Builder(a).setTitle(kind.equals("templates")?"共享模板":"数据插件 · 不执行代码").setItems(names,(d,n)->{try{JSONObject item=list.getJSONObject(n);if(kind.equals("templates"))a.integrations.previewTemplate(item);else new AlertDialog.Builder(a).setTitle(item.optString("name")).setMessage(pluginText(item,java.time.LocalDate.now(ScreenData.ZONE))+"\n\n显示到下方卡片，局部更新。").setNegativeButton("取消",null).setPositiveButton("使用插件",(x,w)->{try{validatePlugin(item);a.cfg.put("plugin",item).put("card2","plugin").put("cardsVersion",1);a.screenChanged();a.sync(false,false);}catch(Exception e){a.toast(e.getMessage());}}).show();}catch(Exception e){a.toast(e.getMessage());}}).show();}catch(Exception e){a.toast(e.getMessage());}});}
 static void validatePlugin(JSONObject p)throws Exception{if(!p.optString("schema").equals("mojian-card-v1")||p.toString().length()>5000)throw new Exception("插件版本或长度不支持");String kind=p.optString("kind");if(kind.equals("text")){if(p.getString("text").length()>100)throw new Exception("插件文字过长");}else if(kind.equals("countdown")){java.time.LocalDate.parse(p.getString("date"));if(p.getString("title").length()>30)throw new Exception("名称过长");}else if(kind.equals("daily")){JSONArray list=p.getJSONArray("items");if(list.length()<1||list.length()>31)throw new Exception("短句数量无效");for(int i=0;i<list.length();i++)if(list.getString(i).length()>100)throw new Exception("短句过长");}else throw new Exception("插件类型不支持，不执行脚本");}
 static String pluginText(JSONObject p,java.time.LocalDate day){try{validatePlugin(p);switch(p.getString("kind")){case "countdown":long left=java.time.temporal.ChronoUnit.DAYS.between(day,java.time.LocalDate.parse(p.getString("date")));return p.getString("title")+"\n"+(left==0?"就是今天":left>0?"还有 "+left+" 天":"已过 "+(-left)+" 天");case "daily":JSONArray list=p.getJSONArray("items");return list.getString(day.getDayOfYear()%list.length());default:return p.getString("text");}}catch(Exception e){return "插件数据无效";}}
 void inbox(){final JSONObject[] response={null};a.work("读取留言收件箱",()->response[0]=call("messages","GET",null),()->{try{JSONArray list=response[0].getJSONArray("items");java.util.List<JSONObject> pending=new java.util.ArrayList<>();for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optString("status").equals("pending"))pending.add(list.getJSONObject(i));if(pending.isEmpty()){a.toast("没有待处理留言");return;}String[] names=new String[pending.size()];for(int i=0;i<names.length;i++)names[i]=pending.get(i).optString("sender")+"："+pending.get(i).optString("text");new AlertDialog.Builder(a).setTitle("待确认留言").setItems(names,(d,n)->{JSONObject item=pending.get(n);new AlertDialog.Builder(a).setTitle(item.optString("sender")).setMessage(item.optString("text")+"\n\n接受后放到小纸条卡片，不修改待办。").setNegativeButton("稍后",null).setNeutralButton("忽略",(x,w)->review(item,false)).setPositiveButton("显示到屏幕",(x,w)->review(item,true)).show();}).show();}catch(Exception e){a.toast(e.getMessage());}});}
 void review(JSONObject item,boolean accept){try{if(accept){a.cfg.put("note",item.getString("text")).put("card2","note").put("cardsVersion",1);a.screenChanged();a.sync(false,false);}a.worker.execute(()->{try{call("messages/"+item.getString("id"),"PUT",new JSONObject().put("status",accept?"accepted":"dismissed"));}catch(Exception e){a.ui.post(()->a.toast("留言状态未回传，可稍后重试"));}});}catch(Exception e){a.toast(e.getMessage());}}
 void sendMessage(){LinearLayout form=new LinearLayout(a);form.setOrientation(1);EditText sender=a.field(form,"留言署名","");EditText message=a.field(form,"留言内容（最多100字）","");AlertDialog dialog=new AlertDialog.Builder(a).setTitle("留言至已配置共享服务").setView(a.scrollForm(form)).setNegativeButton("取消",null).setPositiveButton("发送",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{String who=sender.getText().toString().trim(),value=message.getText().toString().trim();if(who.isEmpty()||who.length()>30||value.isEmpty()||value.length()>100)throw new Exception("署名1至30字，内容1至100字");JSONObject body=new JSONObject().put("sender",who).put("text",value);dialog.dismiss();a.clearDraft("留言署名");a.clearDraft("留言内容（最多100字）");a.work("发送留言",()->call("messages","POST",body),()->{a.message="已进入收件箱，等待屏幕主人确认";});}catch(Exception e){a.toast(e.getMessage());}}));dialog.show();}
}
